//! The record of the host calls of a page (docs/spec/logging.md#entrances): every command that the page calls is the event
//! `host.binding.call`, whether or not the performance trace is on. A command is defined only inside `bindings!`
//! (bindings.rs), which gives it a [`BindingCall`] as its first argument and records the call when the command returns.
//! The registration of the commands is generated by the same macro, so a command that is registered is recorded.

use std::fmt::Display;
use std::time::Instant;

use serde_json::json;
use tauri::ipc::{CommandArg, CommandItem, InvokeBody, InvokeError};

use crate::bounds::{bounded_json, cut_text, CALL_TEXT_BYTES};
use crate::event_log::{valid_cid, Level};
use crate::event_record::{emit_host, emit_host_cids};
use crate::log_policy::Class;

/// The code of the error of a call that fails without a code of its own.
const INTERNAL_CODE: i64 = -32603;

/// One command being handled: its name, the arguments of the call cut to the bound, and the time it started. A call that is
/// dropped before [`BindingCall::finish`] ended without a result: the framework rejected an argument, or the command
/// panicked.
pub struct BindingCall {
    name: String,
    /// The text of each argument by its key, each cut to the bound while it is serialized.
    arguments: Vec<(String, String, bool)>,
    /// The correlation identifiers of the operation that the call carries out (the key `cids` of the payload, which is not an
    /// argument of the command; docs/spec/logging.md#operation-chains).
    cids: Vec<String>,
    /// Why the call is refused: an identifier that is not a list of identifiers a line can hold.
    refusal: Option<String>,
    started: Instant,
    finished: bool,
}

impl BindingCall {
    /// Starts the record of the command `name` called with `payload`. Each argument is serialized only up to the bound.
    pub fn begin(name: &str, payload: &InvokeBody) -> BindingCall {
        let started = Instant::now();
        let mut cids = Vec::new();
        let mut refusal = None;
        if let InvokeBody::Json(serde_json::Value::Object(map)) = payload {
            if let Some(found) = map.get("cids") {
                match found.as_array().map(|list| {
                    list.iter()
                        .map(|cid| cid.as_str().filter(|cid| valid_cid(cid)).map(str::to_string))
                        .collect::<Option<Vec<String>>>()
                }) {
                    Some(Some(list)) => cids = list,
                    _ => {
                        refusal = Some(format!(
                            "cids of the call {name}: {found} is not a list of identifiers that are not empty and hold no quote, backslash or control character"
                        ))
                    }
                }
            }
        }
        // The arguments are kept for the event of a success or of a failure; when the policy stores neither, they are not cut.
        let stored = crate::log_policy::event_enabled(Class::Call, Level::Debug)
            || crate::log_policy::event_enabled(Class::Call, Level::Warn);
        let arguments = match payload {
            InvokeBody::Json(serde_json::Value::Object(map)) if stored => map
                .iter()
                .filter(|(key, _)| key.as_str() != "cids")
                .map(|(key, value)| {
                    let (text, truncated) = bounded_json(value, CALL_TEXT_BYTES);
                    (key.clone(), text, truncated)
                })
                .collect(),
            _ => Vec::new(),
        };
        BindingCall {
            name: name.to_string(),
            arguments,
            cids,
            refusal,
            started,
            finished: false,
        }
    }

    /// Why the call must be refused, or `None` when its identifiers are valid.
    pub fn refusal(&self) -> Option<&str> {
        self.refusal.as_deref()
    }

    /// Ends the call as refused: the event states the reason as the error and carries no identifiers.
    pub fn refuse(mut self, reason: String) {
        self.finished = true;
        self.cids = Vec::new();
        self.emit(&[], Some(reason));
    }

    /// Stores the event with the result and the microseconds since the call began. `names` are the parameters of the command
    /// in the order of the call; the arguments are the JSON array of the values of the parameters that the call sent. A failed
    /// command is at the level `warn`, and its error text is the text that the page receives.
    pub fn finish<T, E: Display>(mut self, names: &[&str], result: &Result<T, E>) {
        self.finished = true;
        let ordered: Vec<&(String, String, bool)> = names
            .iter()
            .filter_map(|name| self.arguments.iter().find(|(key, _, _)| key == name))
            .collect();
        match result {
            Ok(_) => self.emit(&ordered, None),
            Err(error) => self.emit(&ordered, Some(error.to_string())),
        }
    }

    fn emit(&self, arguments: &[&(String, String, bool)], error: Option<String>) {
        // The gate is asked before the arguments are joined and the fields are built: a call that the policy does not store costs one
        // branch.
        let level = if error.is_none() {
            Level::Debug
        } else {
            Level::Warn
        };
        if !crate::log_policy::gate_event(Class::Call, level) {
            return;
        }
        let micros = self.started.elapsed().as_micros() as u64;
        let mut args = String::from("[");
        let mut truncated = false;
        for (index, (_, text, cut)) in arguments.iter().map(|argument| &**argument).enumerate() {
            if index > 0 {
                args.push(',');
            }
            args.push_str(text);
            truncated |= *cut;
        }
        args.push(']');
        if args.len() > CALL_TEXT_BYTES {
            args = cut_text(&args, CALL_TEXT_BYTES).0;
            truncated = true;
        }
        let (level, fields) = match error {
            None => (
                Level::Debug,
                json!({"name": self.name, "args": args, "micros": micros, "ok": true, "truncated": truncated}),
            ),
            Some(error) => {
                // A command fails with text only, so its code is the internal code of the entrance (docs/spec/logging.md#result-form).
                let (error, cut) = cut_text(&format!("{INTERNAL_CODE}: {error}"), CALL_TEXT_BYTES);
                (
                    Level::Warn,
                    json!({"name": self.name, "args": args, "micros": micros, "ok": false, "truncated": truncated || cut, "error": error}),
                )
            }
        };
        if self.cids.is_empty() {
            emit_host(level, "host.binding.call", fields);
        } else {
            emit_host_cids(level, "host.binding.call", &self.cids, fields);
        }
    }
}

impl Drop for BindingCall {
    fn drop(&mut self) {
        if self.finished {
            return;
        }
        self.finished = true;
        // The names of the parameters are not known here, so the arguments are in the order of their keys.
        let arguments: Vec<&(String, String, bool)> = self.arguments.iter().collect();
        self.emit(&arguments, Some("the call ended without a result".into()));
    }
}

impl<'a, R: tauri::Runtime> CommandArg<'a, R> for BindingCall {
    fn from_command(command: CommandItem<'a, R>) -> Result<Self, InvokeError> {
        let call = BindingCall::begin(command.name, command.message.payload());
        match call.refusal().map(str::to_string) {
            Some(reason) => {
                call.refuse(reason.clone());
                Err(InvokeError::from(reason))
            }
            None => Ok(call),
        }
    }
}
